scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_oncellclick = function(row, col) {
    var rrowIdx = dataList1.getRealRowIndex(row);
    console.log("===================================");
    console.log('row ::: ' + row + ' , col ::: ' + col);
    console.log('getCellDisplayData ::: ' + grid1.getCellDisplayData(row, col));
    log1 = grid1.getCellDisplayData(row, col);
    console.log('getAllDisplayData ::: ');
    console.log(grid1.getAllDisplayJSON());
    log = grid1.getAllDisplayJSON();
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.checkValue = function(log) {
    for (i = 0; i < log.length; i++) {
        if (log[i].col3 == (i + 1)) {
            return true;
        } else {
            return false;
            break;
        }
    }
}
scwin.trigger2_onclick = function(e) {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_header3_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log1 == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "log[0].col3 == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log[29].col3 == '30'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
